export const meta = {
  name: 'review-two-plans',
  description: 'Four architect reviews each for the spawn-offload and git-launch-budget plans',
  phases: [{ title: 'Review', detail: 'Fable, Astra, Sol, Opus per plan' }],
}

const REPO = 'C:\\Users\\khair\\Code Projects\\fork-superset-windows-arm64'
const PLANS = [
  { key: 'spawn-offload', file: `${REPO}\\tmp\\plans\\spawn-offload.md`, goal: 'route every git/gh process creation in the host-service off its main thread via a ChildProcess.prototype.spawn funnel and one spawner worker, so terminal I/O and HTTP never wait on a launch; crash budget exhausted -> refuse with a clear error' },
  { key: 'git-launch-budget', file: `${REPO}\\tmp\\plans\\git-launch-budget.md`, goal: 'cut git/gh launches per minute (PR-sync trigger throttle, single-spawn branch status, isGitRepo dedupe + 60 s yes-TTL, origin/HEAD 10-min cache, ignored-dirs 60 s floor, worktree batch 2 s, ShipControl poll 30 s) without J' },
]
const REVIEWERS = ['architect-fable', 'architect-astra', 'architect-sol', 'architect-opus']

const FINDINGS = {
  type: 'object',
  properties: {
    verdict: { type: 'string', enum: ['sound', 'revise'] },
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          severity: { type: 'string', enum: ['BLOCKER', 'MAJOR', 'MINOR'] },
          title: { type: 'string' },
          where: { type: 'string', description: 'file:line' },
          failure: { type: 'string', description: 'concrete failure scenario' },
          fix: { type: 'string' },
        },
        required: ['severity', 'title', 'where', 'failure', 'fix'],
      },
    },
  },
  required: ['verdict', 'findings'],
}

phase('Review')
const jobs = PLANS.flatMap(p => REVIEWERS.map(r => ({ p, r })))
const results = await parallel(jobs.map(({ p, r }) => () =>
  agent(`Read-only plan review. Do not edit files.

Plan: ${p.file} (repo ${REPO}, Superset desktop fork, Windows ARM64; AGENTS.md applies). Goal: ${p.goal}. The user's decisions recorded in the plan are final; do not reopen them. Build order across three fixes: tmp/plans/pr-sweep-skips-exited.md (being implemented right now in the working tree, so pull-requests.ts and app.ts are mid-edit), then git-launch-budget, then spawn-offload. Compare anchors against HEAD with \`git show HEAD:<path>\` where the working tree is mid-edit.

Check the plan against the actual code and runtime: wrong anchors; correctness gaps; behaviour regressions; anything that silently hides a failure (user rule: fail fast and loud, no masking fallbacks); upstream-merge footprint and FEATURES.md markers rooted at exact files; interactions with the other two plans; tests (too many, too few, wrong layer); over-engineering. Rank BLOCKER/MAJOR/MINOR with file:line, a concrete failure scenario, and the fix. Set verdict=sound only if nothing above MINOR.`,
    { label: `${p.key}:${r}`, phase: 'Review', agentType: r, schema: FINDINGS })
    .then(res => res && { plan: p.key, reviewer: r, ...res })))
return results.filter(Boolean)

